abstract contract BaseProxy {
    // Abstract — derived contract must override
    function _getTarget() internal view virtual returns (address);

    function _delegate(bytes calldata data) internal returns (bytes memory) {
        address target = _getTarget();  // abstract — cannot analyze
        (bool ok, bytes memory ret) = target.delegatecall(data);
        require(ok, "delegatecall failed");
        return ret;
    }
}

