contract SecureProxy is TransparentUpgradeableProxy {
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    // TimelockController with 72-hour minimum delay
    address public immutable timelockController;

    function upgradeTo(address newImplementation) external override {
        require(hasRole(UPGRADER_ROLE, msg.sender), "missing upgrader role");
        // _authorizeUpgrade checks timelock proposal was made >= 72h ago
        _authorizeUpgrade(newImplementation);
        _upgradeTo(newImplementation);
    }

    function _authorizeUpgrade(address newImpl) internal override {
        ITimelockController(timelockController).assertProposed(newImpl, 72 hours);
    }
}

interface IENS {
    function resolver(bytes32 node) external view returns (address);
}

contract ENSProxy {
    IENS public immutable ens;
    bytes32 public pluginNode;  // ENS node hash for plugin

    function _getPlugin() internal view returns (address) {
        address resolver = ens.resolver(pluginNode);
        return IResolver(resolver).addr(pluginNode);  // ENS resolution
    }

    function executePlugin(bytes calldata data) external onlyOwner {
        address plugin = _getPlugin();
        (bool ok,) = plugin.delegatecall(data);  // delegatecall to ENS-resolved addr
        require(ok);
    }
}

function _computeImplementation(bytes32 salt) internal view returns (address) {
    return address(uint160(uint256(keccak256(abi.encodePacked(
        bytes1(0xff),
        factory,
        salt,
        keccak256(type(Implementation).creationCode)  // only checks type hash, not deployed code
    )))));
}

function delegateToImplementation(bytes32 salt, bytes calldata data) external onlyOwner {
    address impl = _computeImplementation(salt);
    // VULNERABILITY: no check that impl is actually deployed or has correct bytecode
    (bool ok,) = impl.delegatecall(data);
    require(ok);
}
